  "ARMING_OPTIONS": {
      "name": "ARMING_OPTIONS",
      "displayName": "Arming options",
      "description": "Options that can be applied to change arming behaviour",
      "group": "ARMING_",
      "category": "ARMING",
      "userLevel": "Advanced",
      "dataType": "bitmask",
      "bitmask": {
          "0": "Disable prearm display",
          "1": "Do not send status text on state change",
          "2": "Skip IMU consistency checks when ICE motor running"
      },
      "rebootRequired": false,
      "tags": [
          "arming",
          "bitmask"
      ]
  },
  "ARMING_REQUIRE": {
      "name": "ARMING_REQUIRE",
      "displayName": "Require Arming Motors",
      "description": "Arming disabled until some requirements are met. If 0, there are no requirements (arm immediately).  If 1, all checks specified by ARMING_CHECKS must pass before the vehicle can be armed (for example, via rudder stick or GCS command).  If 3, Arm immediately once pre-arm/arm checks are satisfied, but only one time per boot up.  Note that a reboot is NOT required when setting to 0 but IS require when setting to 3.",
      "group": "ARMING_",
      "category": "ARMING",
      "userLevel": "Advanced",
      "dataType": "enum",
      "values": {
          "0": "No",
          "1": "Yes(minimum PWM when disarmed)",
          "3": "No(AutoArmOnce after checks are passed)"
      },
      "rebootRequired": false,
      "tags": [
          "arming",
          "enum"
      ]
  },
  "ARMING_RUDDER": {
      "name": "ARMING_RUDDER",
      "displayName": "Arming with Rudder enable/disable",
      "description": "Allow arm/disarm by rudder input. When enabled arming can be done with right rudder, disarming with left rudder. Rudder arming only works with throttle at zero +- deadzone (RCx_DZ). Depending on vehicle type, arming in certain modes is prevented. See the wiki for each vehicle. Caution is recommended when arming if it is allowed in an auto-throttle mode!",
      "group": "ARMING_",
      "category": "ARMING",
      "userLevel": "Advanced",
      "dataType": "enum",
      "values": {
          "0": "Disabled",
          "1": "ArmingOnly",
          "2": "ArmOrDisarm"
      },
      "rebootRequired": false,
      "tags": [
          "arming",
          "enable",
          "enum"
      ]
  },
