  "EK3_SRC_OPTIONS": {
      "name": "EK3_SRC_OPTIONS",
      "displayName": "EKF Source Options",
      "description": "EKF Source Options. Bit 0: Fuse all velocity sources present in EK3_SRCx_VEL_. Bit 1: Align external navigation position when using optical flow. Bit 3: Use SRC per core. By default, EKF source selection is controlled via the EK3_SRC parameters, allowing only one source to be active at a time across all cores (switchable via MAVLink, Lua, or RC). Enabling this bit maps EKF core 1 to SRC1, core 2 to SRC2, etc., allowing each core to run independently with a dedicated source.",
      "group": "EK3_SRC",
      "category": "EK3",
      "userLevel": "Advanced",
      "dataType": "bitmask",
      "bitmask": {
          "0": "FuseAllVelocities",
          "1": "AlignExtNavPosWhenUsingOptFlow",
          "3": "UsePerCoreEKFSources"
      },
      "rebootRequired": false,
      "tags": [
          "ek3",
          "bitmask"
      ]
  },
  "ESC_TLM_MAV_OFS": {
      "name": "ESC_TLM_MAV_OFS",
      "displayName": "ESC Telemetry mavlink offset",
      "description": "Offset to apply to ESC numbers when reporting as ESC_TELEMETRY packets over MAVLink. This allows high numbered motors to be displayed as low numbered ESCs for convenience on GCS displays. A value of 4 would send ESC on output 5 as ESC number 1 in ESC_TELEMETRY packets",
      "group": "ESC_TLM",
      "category": "MISC",
      "userLevel": "Standard",
      "dataType": "int",
      "increment": 1,
      "rebootRequired": false,
      "tags": [
          "esc"
      ],
      "range": {
          "min": 0,
          "max": 31
      }
  },
