      "displayName": "Rally Include Home",
      "description": "Controls if Home is included as a Rally point (i.e. as a safe landing place) for RTL",
      "group": "RALLY_",
      "category": "MISC",
      "userLevel": "Standard",
      "dataType": "enum",
      "values": {
          "0": "DoNotIncludeHome",
          "1": "IncludeHome"
      },
