          "4": "RX_PullDown",
          "5": "RX_PullUp",
          "6": "TX_PullDown",
          "7": "TX_PullUp",
          "8": "RX_NoDMA",
          "9": "TX_NoDMA",
          "10": "Don't forward mavlink to/from (moved to MAVn_OPTIONS >4.7)",
          "11": "DisableFIFO",
          "12": "Ignore Streamrate (moved to MAVn_OPTIONS >4.7)"
